import json, re
from collections import Counter
from pathlib import Path
from urllib.parse import unquote, urlparse, parse_qs

WHITELIST = {
    "csv","tsv","parquet","pdf","tif","tiff","nc","netcdf","json","geojson","xml",
    "zip","gz","tgz","tar","bz2","xz","7z","rar","gpkg","txt","html","htm",
    "xls","xlsx","png","jpg","jpeg","gif","shp","kml","kmz","grib","grib2",
    "hdf","h5","hdf5","zarr","asc","img","fasta","fa","dat","mat","rmd","md",
    "doc","docx","pptx","gml","fgdc","eml","rdf","ttl","dwca","jp2","las","laz",
    "feather","arrow","ncml","bag","kmz","topojson","geojson","gpkg",
}
# single-letter code files are real but rare; include r separately
WHITELIST.add("r")
INNER = WHITELIST - {"gz","bz2","xz","tgz","zip","7z","rar","tar"}
COMP = {"gz","bz2","xz","tgz","zip","7z"}

def filename_suffix(name: str) -> str | None:
    name = unquote(name).strip().lower().rstrip(".,);\"'")
    name = name.rsplit("/", 1)[-1]
    if not name or name.endswith("/"):
        return None
    m = re.fullmatch(r".+\.([a-z0-9]{1,10})\.([a-z0-9]{1,5})", name)
    if m and m.group(1) in INNER and m.group(2) in COMP:
        return f"{m.group(1)}.{m.group(2)}"
    m = re.fullmatch(r".+\.([a-z0-9]{1,10})", name)
    if m and m.group(1) in WHITELIST:
        return m.group(1)
    return None

def classify(url: str) -> str:
    text = unquote(url.replace("&amp;", "&"))
    text = text.split("#", 1)[0]
    parsed = urlparse(text)
    path = parsed.path or ""
    seg = path.rstrip("/").rsplit("/", 1)[-1] if path.rstrip("/") else ""
    hit = filename_suffix(seg)
    if hit:
        return hit
    # filename-like query values
    q = parsed.query.replace("&amp;", "&")
    # parse_qs needs a scheme-less query; keep plus signs
    try:
        params = parse_qs(q, keep_blank_values=True)
    except Exception:
        params = {}
    for vals in params.values():
        for v in vals:
            hit = filename_suffix(v)
            if hit:
                return hit
    # raw scan of query for files=name.ext already covered
    return "unknown"

def shape(url: str) -> str:
    text = unquote(url.replace("&amp;", "&")).lower()
    p = urlparse(text.split("#",1)[0])
    path = p.path
    if "archive.do" in path or path.endswith(".do"):
        return "service: ipt archive.do (no extension)"
    if any(x in path for x in ("/wms", "/ows", "wmsserver", "mapserv")) or "service=wms" in text or "request=getcapabilities" in text:
        return "service: WMS/OWS"
    if "erddap" in text and path.endswith(".graph"):
        return "service: ERDDAP .graph"
    if "doi.org" in p.netloc or p.path.startswith("/10.") or "/doi" in path:
        return "landing: doi"
    if "github.com" in p.netloc or "radiantearth.github.io" in p.netloc:
        return "landing: github/stac page"
    if "securegetobj.php" in path or path.endswith(".php"):
        return "opaque: php id, no filename"
    if "index.php/s/" in path or "/index.php/s/" in path:
        return "share link, no filename in URL"
    if path.endswith("/") or path == "":
        return "directory or bare URL"
    if text.startswith("s3://") and "bundled-parquet" in text:
        return "s3 path token bundled-parquet, no .parquet suffix"
    if text.startswith("s3://"):
        return "s3 path, no file suffix"
    return "other, no recognized suffix"

for name in ["deepoceans","ecoforecast","earthsurface","facetsearch"]:
    data = json.loads(Path(f"/tmp/decoder-dist/{name}-content.json").read_text())
    urls = [r["url"] for r in data["rows"]]
    c = Counter(classify(u) for u in urls)
    n = len(urls)
    unk = [u for u in urls if classify(u)=="unknown"]
    shapes = Counter(shape(u) for u in unk)
    print("="*72)
    print(f"{name}: distinct schema:contentUrl on schema:DataDownload = {n}")
    print(f"{'type':18} {'n':>7} {'pct':>7}")
    for ext, k in c.most_common():
        if k < 3 and ext != "unknown":
            continue
        label = "unknown" if ext=="unknown" else "."+ext
        print(f"{label:18} {k:7} {100*k/n:6.1f}%")
    small = [(e,k) for e,k in c.items() if k < 3 and e != "unknown"]
    if small:
        print(f"{'(ext n<3)':18} {sum(k for _,k in small):7}  {', '.join('.'+e for e,_ in sorted(small))}")
    print("unknown breakdown:")
    for s,k in shapes.most_common():
        print(f"  {k:6}  {s}")
