import json, re
from collections import Counter
from pathlib import Path
from urllib.parse import unquote, urlparse, parse_qs

WHITELIST = {
    "csv","tsv","parquet","pdf","tif","tiff","nc","netcdf","json","geojson","xml",
    "zip","gz","tgz","tar","bz2","xz","7z","rar","gpkg","txt","html","htm",
    "xls","xlsx","png","jpg","jpeg","gif","shp","kml","kmz","grib","grib2",
    "hdf","h5","hdf5","zarr","asc","img","fasta","fa","dat","mat","rmd","md",
    "doc","docx","pptx","gml","fgdc","eml","rdf","ttl","dwca","jp2","las","laz",
    "feather","arrow","ncml","bag","topojson","r",
}
INNER = WHITELIST - {"gz","bz2","xz","tgz","zip","7z","rar","tar"}
COMP = {"gz","bz2","xz","tgz","zip","7z"}

def filename_suffix(name: str):
    name = unquote(name).strip().lower().rstrip(".,);\"'")
    name = name.rsplit("/", 1)[-1]
    if not name:
        return None
    m = re.fullmatch(r".+\.([a-z0-9]{1,10})\.([a-z0-9]{1,5})", name)
    if m and m.group(1) in INNER and m.group(2) in COMP:
        return f"{m.group(1)}.{m.group(2)}"
    m = re.fullmatch(r".+\.([a-z0-9]{1,10})", name)
    if m and m.group(1) in WHITELIST:
        return m.group(1)
    return None

def classify(url: str) -> str:
    text = unquote(url.replace("&amp;", "&")).split("#", 1)[0]
    parsed = urlparse(text)
    seg = (parsed.path or "").rstrip("/").rsplit("/", 1)[-1]
    hit = filename_suffix(seg)
    if hit:
        return hit
    try:
        params = parse_qs(parsed.query.replace("&amp;", "&"), keep_blank_values=True)
    except Exception:
        params = {}
    for vals in params.values():
        for v in vals:
            hit = filename_suffix(v)
            if hit:
                return hit
    return "unknown"

def host(url):
    return urlparse(unquote(url.replace("&amp;", "&"))).netloc

out = {}
for name in ["deepoceans","ecoforecast","earthsurface","facetsearch"]:
    urls = [r["url"] for r in json.loads(Path(f"/tmp/decoder-dist-v2/{name}-content.json").read_text())["rows"]]
    c = Counter(classify(u) for u in urls)
    unk = [u for u in urls if classify(u) == "unknown"]
    shapes = Counter()
    for u in unk:
        text = unquote(u.replace("&amp;", "&")).lower()
        p = urlparse(text.split("#", 1)[0])
        path = p.path
        if "archive.do" in path or path.endswith(".do"):
            shapes["ipt"] += 1
        elif any(x in path for x in ("/wms", "/ows", "wmsserver", "mapserv")) or "service=wms" in text or "request=getcapabilities" in text:
            shapes["wms"] += 1
        elif "erddap" in text and path.endswith(".graph"):
            shapes["erddap_graph"] += 1
        elif "doi.org" in p.netloc or p.path.startswith("/10.") or "/doi" in path:
            shapes["doi"] += 1
        elif "github.com" in p.netloc or "radiantearth.github.io" in p.netloc:
            shapes["github"] += 1
        elif "securegetobj.php" in path:
            shapes["iodp"] += 1
        elif path.endswith(".php"):
            shapes["php"] += 1
        elif "index.php/s/" in path:
            shapes["share"] += 1
        elif text.startswith("s3://") and "bundled-parquet" in text:
            shapes["s3_parquet_token"] += 1
        elif text.startswith("s3://"):
            shapes["s3"] += 1
        elif path.endswith("/") or path == "":
            shapes["dir"] += 1
        elif "bco-dmo.org" in p.netloc:
            shapes["bco"] += 1
        else:
            shapes["other"] += 1
    tif = [u for u in urls if classify(u) == "tif"]
    tif_query = sum(1 for u in tif if ".tif" not in urlparse(unquote(u.replace("&amp;", "&"))).path.lower())
    parquet_token = sum("parquet" in u.lower() for u in urls)
    parquet_suffix = sum(u.lower().split("?")[0].rstrip("/").endswith(".parquet") for u in urls)
    out[name] = {
        "n": len(urls),
        "types": c.most_common(),
        "shapes": shapes.most_common(),
        "tif_query": tif_query,
        "parquet_token": parquet_token,
        "parquet_suffix": parquet_suffix,
    }
    print("=" * 60, name, len(urls))
    for ext, k in c.most_common():
        print(f"  {ext:16} {k:7} {100*k/len(urls):6.1f}")
    print("  shapes", shapes.most_common())
    print("  tif_query", tif_query, "parquet_token", parquet_token, "parquet_suffix", parquet_suffix)

Path("/tmp/decoder-dist-v2/summary.json").write_text(json.dumps(out))
PY

