python3 << 'PY'
import json, re
from collections import Counter, defaultdict
from pathlib import Path
from urllib.parse import unquote, urlparse, parse_qs

WHITELIST = {
    "csv","tsv","parquet","pdf","tif","tiff","nc","netcdf","json","geojson","xml",
    "zip","gz","tgz","tar","bz2","xz","7z","rar","gpkg","txt","html","htm",
    "xls","xlsx","png","jpg","jpeg","gif","shp","kml","kmz","grib","grib2",
    "hdf","h5","hdf5","zarr","asc","img","fasta","fa","dat","mat","rmd","md",
    "doc","docx","pptx","gml","fgdc","eml","rdf","ttl","dwca","jp2","las","laz",
    "feather","arrow","ncml","bag","topojson","r","rtf","ps","mp4","mov","ppt","odv","fli",
}
INNER = WHITELIST - {"gz","bz2","xz","tgz","zip","7z","rar","tar"}
COMP = {"gz","bz2","xz","tgz","zip","7z"}
MIME = {
    "text/csv":"csv","text/tab-separated-values":"tsv","text/plain":"txt","text/html":"html",
    "text/xml":"xml","application/xml":"xml","application/json":"json","application/geo+json":"geojson",
    "application/pdf":"pdf","application/zip":"zip","application/x-zip-compressed":"zip",
    "application/gzip":"gz","application/x-gzip":"gz","application/x-tar":"tar",
    "application/x-netcdf":"nc","application/netcdf":"nc","application/x-hdf":"hdf",
    "application/x-hdf5":"hdf5","application/x-parquet":"parquet","image/tiff":"tif",
    "image/geotiff":"tif","application/geotiff":"tif","application/geopackage+vnd.sqlite3":"gpkg",
    "image/png":"png","image/jpeg":"jpeg","image/gif":"gif","application/vnd.ms-excel":"xls",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet":"xlsx",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document":"docx",
    "application/msword":"doc","application/vnd.ms-powerpoint":"ppt",
    "application/vnd.google-earth.kml+xml":"kml","application/gml+xml":"gml",
    "application/x-fasta":"fasta","application/r":"r","video/mp4":"mp4","video/quicktime":"mov",
    "image/x-jp2":"jp2","text/rtf":"rtf","application/postscript":"ps","application/vnd.shp":"shp",
    "application=geotiff":"tif","earthref-tsv-multipart":"tsv",
    "application/vnd.ogc.wms_xml":"xml","application/vnd.ogc.wfs_xml":"xml",
    "text/x-odv":"odv","video/fli":"fli",
}

def filename_suffix(name):
    name = unquote(name).strip().lower().rstrip(".,);\"'")
    name = name.rsplit("/",1)[-1]
    if not name: return None
    m = re.fullmatch(r".+\.([a-z0-9]{1,10})\.([a-z0-9]{1,5})", name)
    if m and m.group(1) in INNER and m.group(2) in COMP:
        return f"{m.group(1)}.{m.group(2)}"
    m = re.fullmatch(r".+\.([a-z0-9]{1,10})", name)
    if m and m.group(1) in WHITELIST:
        return m.group(1)
    return None

def classify_url(url):
    text = unquote(url.replace("&amp;","&")).split("#",1)[0]
    parsed = urlparse(text)
    seg = (parsed.path or "").rstrip("/").rsplit("/",1)[-1]
    hit = filename_suffix(seg)
    if hit: return hit
    try:
        params = parse_qs(parsed.query.replace("&amp;","&"), keep_blank_values=True)
    except Exception:
        params = {}
    for vals in params.values():
        for v in vals:
            hit = filename_suffix(v)
            if hit: return hit
    return "unknown"

def fmt_types(raw):
    text = raw.strip()
    if text.startswith("[") and text.endswith("]"):
        text = text[1:-1].strip()
    text = text.strip().lower()
    if text in ("","null","none"): return set()
    if text.startswith("www:") or text.startswith("ogc:") or text in {"doi","order","application/octet-stream"}: return set()
    if text.startswith("http://") or text.startswith("https://"): return set()
    if text == "profile=cloud-optimized": return set()
    if text in MIME: return {MIME[text]}
    parts = [p.strip() for p in text.split(";") if p.strip()]
    types=set()
    for p in parts:
        if p in MIME: types.add(MIME[p])
        elif p.startswith("application=") and p.split("=",1)[1] in {"geotiff","tiff"}: types.add("tif")
        elif p.startswith("application=") and p.endswith("-tsv"): types.add("tsv")
        else:
            types.add("UNRECOGNIZED")
    return types

# Yale-style veto only where we actually read a description that states a second type.
# Checked earthsurface text hits: viewcontent filename=1 states both ZIP and GeoTIFF.
VETO = {
    "https://elischolar.library.yale.edu/cgi/viewcontent.cgi?article=1000&context=yale_fes_data&filename=1&type=additional"
}

for name in ["deepoceans","ecoforecast","earthsurface","facetsearch"]:
    urls = [r["url"] for r in json.loads(Path(f"/tmp/decoder-dist-v2/{name}-content.json").read_text())["rows"]]
    pairs = json.loads(Path(f"/tmp/decoder-dist-v3/{name}-fmt.json").read_text())["rows"]
    by=defaultdict(set)
    for row in pairs:
        by[row["url"]].update(fmt_types(row["fmt"]))
    url_only = Counter(classify_url(u) for u in urls)
    final = Counter()
    resolved = Counter()
    conflict = 0
    still = 0
    for u in urls:
        base = classify_url(u)
        if base != "unknown":
            final[base] += 1
            continue
        if u in VETO:
            conflict += 1
            still += 1
            final["unknown"] += 1
            continue
        types={t for t in by.get(u,set()) if t != "UNRECOGNIZED"}
        bad = "UNRECOGNIZED" in by.get(u,set())
        if len(types)==1 and not bad:
            t=next(iter(types))
            resolved[t]+=1
            final[t]+=1
        else:
            if len(types)>1 or bad:
                conflict += 1
            still += 1
            final["unknown"] += 1
    n=len(urls)
    print("="*64)
    print(name, "n", n)
    print(f"unknown {url_only['unknown']} -> {final['unknown']}  resolved {sum(resolved.values())}  conflict_or_veto {conflict}")
    print("resolved_from_fmt", resolved.most_common())
    print("final top")
    for t,k in final.most_common(12):
        print(f"  {t:12} {k:7} {100*k/n:5.1f}%   was {url_only[t]}")
PY

